From e9fa1d44afb12ec8c17f984c1e464d421b3ad2fb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:39:40 +0100
Subject: [PATCH] libkmpris/kded: use the system volume step for media volume
 shortcuts

The "Media volume up" and "Media volume down" global shortcuts always
changed the player's volume by 5%, ignoring the volume step set in the
audio settings. They now read that step, like the Media Player widget.

BUG: 505557
---
 libkmpris/kded/CMakeLists.txt   |  1 +
 libkmpris/kded/mprisservice.cpp | 11 +++++++++--
 libkmpris/kded/mprisservice.h   |  3 +++
 3 files changed, 13 insertions(+), 2 deletions(-)

diff --git a/libkmpris/kded/CMakeLists.txt b/libkmpris/kded/CMakeLists.txt
index f1c49e2523..8dc4b28c86 100644
--- a/libkmpris/kded/CMakeLists.txt
+++ b/libkmpris/kded/CMakeLists.txt
@@ -4,6 +4,7 @@
 kcoreaddons_add_plugin(mprisservice SOURCES mprisservice.cpp mprisservice.h INSTALL_NAMESPACE "kf6/kded")
 target_link_libraries(mprisservice
     Qt::Core
+    KF6::ConfigCore
     KF6::CoreAddons
     KF6::DBusAddons
     KF6::GlobalAccel
diff --git a/libkmpris/kded/mprisservice.cpp b/libkmpris/kded/mprisservice.cpp
index 32a7593811..7ee808cb8a 100644
--- a/libkmpris/kded/mprisservice.cpp
+++ b/libkmpris/kded/mprisservice.cpp
@@ -8,6 +8,7 @@
 #include "mprisservice.h"

 #include <KActionCollection>
+#include <KConfigGroup>
 #include <KGlobalAccel>
 #include <KLocalizedString>
 #include <KPluginFactory>
@@ -21,6 +22,7 @@ MprisService::MprisService(QObject *parent, const QList<QVariant> &)
     : KDEDModule(parent)
     , m_multiplexer(Multiplexer::self())
     , m_actionCollection(new KActionCollection(this, QStringLiteral("mediacontrol")))
+    , m_audioConfigWatcher(KConfigWatcher::create(KSharedConfig::openConfig(QStringLiteral("plasmaparc"))))
 {
     m_activePlayer.setBinding([this] {
         return m_multiplexer->activePlayer().value();
@@ -112,17 +114,22 @@ void MprisService::onPlay()
     }
 }

+double MprisService::volumeStep() const
+{
+    return m_audioConfigWatcher->config()->group(QStringLiteral("General")).readEntry(QStringLiteral("VolumeStep"), 5) / 100.0;
+}
+
 void MprisService::onVolumeUp()
 {
     if (m_activePlayer && m_activePlayer->canControl()) {
-        m_activePlayer->changeVolume(0.05, true);
+        m_activePlayer->changeVolume(volumeStep(), true);
     }
 }

 void MprisService::onVolumeDown()
 {
     if (m_activePlayer && m_activePlayer->canControl()) {
-        m_activePlayer->changeVolume(-0.05, true);
+        m_activePlayer->changeVolume(-volumeStep(), true);
     }
 }

diff --git a/libkmpris/kded/mprisservice.h b/libkmpris/kded/mprisservice.h
index 7da53b640b..a5faa4b661 100644
--- a/libkmpris/kded/mprisservice.h
+++ b/libkmpris/kded/mprisservice.h
@@ -8,6 +8,7 @@

 #include <QBindable>

+#include <KConfigWatcher>
 #include <KDEDModule>

 class PlayerContainer;
@@ -41,8 +42,10 @@ private Q_SLOTS:

 private:
     void enableGlobalShortcuts();
+    double volumeStep() const;

     std::shared_ptr<Multiplexer> m_multiplexer;
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(MprisService, PlayerContainer *, m_activePlayer, nullptr)
     KActionCollection *const m_actionCollection;
+    KConfigWatcher::Ptr m_audioConfigWatcher;
 };
-- 
